  "2": {   "2": {     "title": "Salle des Rituels Sacrés",     "description": "La salle est petite et rectangulaire, éclairée par une faible lumière qui se répand à peine à travers les piliers et les colonnes vieillies. Les cercles rituels et les glyphes runiques gravés dans le sol semblent avoir été oubliés depuis des siècles. Des cercles de lumière se dessinent sur le sol, marquant les emplacements des anciens autels. Des têtes de mort et des tentacules émergent des murs, ajoutant une atmosphère sinistre à l'endroit. Le mobilier ancien est délabré, et l'eau stagnante dans un coin de la salle rend l'endroit humide et glissant. La seule issue semble être un trou avec grille, qui semble avoir été fermé depuis longtemps.",     "tags": [       "rituel",       "sacrifice",       "vieillissement",       "sinistre",       "salle"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "rectangulaire",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels",         "glyphes runiques"       ],       "architecturalDetails": [         "piliers",         "colonnnes"       ],       "objectsOrFurniture": [         "mobilier ancien"       ],       "creaturesOrTraces": [         "pièges"       ],       "exits": [         "un seul"       ],       "hazards": [         "eau stagnante"       ],       "atmosphere": "sinistre",       "roomPurpose": "salle de rituel",       "csvDescription": "Salle avec un trou avec grille",       "tileNumber": 2     }   } }
