  "3": {   "3": {     "title": "Le Couloir des Anciens",     "description": "Le couloir s'inscrit dans un mur de pierre ancienne, érodée par le temps et la pluie. Les murs, ornés de tentes suspendues, semblent murmurer des secrets millénaires. Des spirales mystérieuses gravées dans le sol indiquent un chemin ancien, peut-être un passage sacré. Les colonnes massives, sculptées de motifs complexes, soutiennent le plafond voûté. Un grand autel ou une plateforme centrale, ornée de symboles énigmatiques, domine le couloir. La lumière naturelle qui filtre à travers les fenêtres éclaire les murs humides et les tapisseries qui flottent doucement. À chaque pas, des apparitions fantomatiques flottent dans l'air, ajoutant une touche de mystère à l'atmosphère déjà ancienne et sacrée. Le couloir semble mener à un lieu plus profond, un sanctuaire ou un lieu de rituel, où les anciens pratiquaient leurs cérémonies et leurs sacrifices.",     "tags": [       "couloir",       "ancien",       "rituel",       "sacré",       "mystère"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "natural light from windows",       "condition": "damp and mossy",       "centralFeature": "central altar or platform",       "wallDecorations": [         "tented wall hangings"       ],       "floorMarkings": [         "spiral patterns"       ],       "architecturalDetails": [         "pillars"       ],       "objectsOrFurniture": [         "table"       ],       "creaturesOrTraces": [         "ghostly apparitions"       ],       "exits": [         "one visible door"       ],       "hazards": [         "mossy floor"       ],       "atmosphere": "mysterious and ancient",       "roomPurpose": "sacred chamber or ritual site",       "csvDescription": "Couloir",       "tileNumber": 3     }   } }
