  "4": {   "4": {     "title": "Passage Sacré",     "description": "Le passage sacré s'inscrit dans un mur de pierre lisse, éclairé par une faible lumière qui se répand dans l'air humide. Les murs, ornés de tentacules et de têtes de mort, semblent veiller sur le passage. Des spirales et un croix sont gravées sur le sol, marquant le chemin à suivre. Des colonnes majestueuses soutiennent le plafond, ajoutant à l'atmosphère mystérieuse. Un autel, dépourvu de tout objet, se dresse au fond du passage, comme témoin silencieux des rituels passés. Les tentacules et les têtes de mort, sculptés dans le mur, semblent attendre l'arrivée de l'aventurier. Le passage est doucement éclairé par une lumière diffuse, rendant l'atmosphère encore plus énigmatique. Les spirales et le croix marquent le chemin à suivre, tandis que les tentacules et les têtes de mort ajoutent une touche d'horreur à l'ambiance. Le passage sacré est un lieu de culte ancien, où les rituels sacrés étaient pratiqués il y a des siècles.",     "tags": [       "Passage",       "Sacré",       "Ancien",       "Tentacules",       "Mystérieux"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "square",       "lighting": "dim",       "condition": "damp",       "centralFeature": "statue",       "wallDecorations": [         "tentsacles",         "heads of death"       ],       "floorMarkings": [         "spirals",         "cross"       ],       "architecturalDetails": [         "pillars"       ],       "objectsOrFurniture": [         "altar"       ],       "creaturesOrTraces": [         "glyphs"       ],       "exits": [         "none"       ],       "hazards": [         "enchanted spiral"       ],       "atmosphere": "mysterious",       "roomPurpose": "sacred chamber",       "csvDescription": "Couloir avec petite salle",       "tileNumber": 4     }   } }
