  "5": {   "5": {     "title": "La Salle Sacrée des Anciens",     "description": "La salle est immense, son plan rectangulaire s'étend sous vos yeux comme un tableau ancien. La lumière tamisée émane des fenêtres étroites, laissant filtrer une lueur froide qui se reflète sur le sol humide. Des colonnes majestueuses soutiennent le plafond, leurs pierres sculptées de motifs complexes. Au centre de la pièce, un autel de pierre est gravé d'un symbole mystérieux, semblant inviter les regards à s'y aduler. Des spirales gravées dans le sol attirent votre attention, semblant former un chemin vers le cœur de la salle. Les murs sont ornés de tentacules et de crânes, rappelant l'ancienne puissance qui a régné ici. L'atmosphère est pesante, presque oppressante, comme si la salle gardait un secret ancien et terrible. Les pas de vos compagnons résonnent dans l'immensité de la pièce, mais il n'y a pas de sortie visible. L'eau stagnante au sol indique que la salle est inondée, ajoutant une touche de danger à l'ambiance déjà sombre.",     "tags": [       "Salle Sacrée",       "Anciens",       "Mystère",       "Sacrifice",       "Pouvoir"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "damp",       "centralFeature": "crown",       "wallDecorations": [         "tentsacles",         "skull"       ],       "floorMarkings": [         "spiral"       ],       "architecturalDetails": [         "pillars"       ],       "objectsOrFurniture": [         "altar"       ],       "creaturesOrTraces": [         "footprints"       ],       "exits": [         "none"       ],       "hazards": [         "water"       ],       "atmosphere": "mysterious",       "roomPurpose": "sacred",       "csvDescription": "Salle",       "tileNumber": 5     }   } }
