  "7": {   "7": {     "title": "Le Couloir des Tentes Sacrées",     "description": "Le couloir s'étend devant vous, large et rectangulaire, éclairé par une faible lumière qui se répand dans l'air humide. Des tentes blanches sont suspendues aux murs, comme des autels silencieux. Le sol est marqué d'un spirale mystérieuse, qui semble guider le regard vers le fond du couloir. Des colonnes majestueuses, ornées de motifs anciens, se dressent de part et d'autre, ajoutant à l'atmosphère sacrée et énigmatique du lieu. Un autel, vide mais majestueux, se dresse au fond du couloir, comme si une cérémonie récente y avait eu lieu. L'humidité qui imprègne l'air rend le couloir presque glissant, et une fine couche d'eau recouvre le sol, créant un miroir qui reflète les tentes et les colonnes. Le mystère qui plane ici est palpable, et chaque détail semble raconter une histoire ancienne et sacrée.",     "tags": [       "Couloir",       "Sacré",       "Tentes",       "Colonne",       "Mystère"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "damp",       "centralFeature": "empty",       "wallDecorations": [         "tents"       ],       "floorMarkings": [         "spiral"       ],       "architecturalDetails": [         "pillars"       ],       "objectsOrFurniture": [         "altar"       ],       "creaturesOrTraces": [         "none"       ],       "exits": [         "none"       ],       "hazards": [         "water"       ],       "atmosphere": "mysterious",       "roomPurpose": "sacred",       "csvDescription": "Couloir",       "tileNumber": 7     }   } }
