  "8": {   "8": {     "title": "Chambre Sacrée des Anciens",     "description": "Vous pénétrez dans une salle immense, aux murs couverts de colonnes massives et de pilastres sculptés. La lumière tamisée émane des fenêtres étroites, laissant filtrer une lueur sombre qui éclaire les spirales et les croix gravées sur le sol. L'atmosphère est oppressante, comme si la présence des anciens observateurs vous observait depuis les ténèbres. Des objets mystérieux sont disséminés un peu partout, leurs formes étranges et leurs couleurs énigmatiques. Des tentacules et des têtes de mort ornent les murs, ajoutant à l'aura sacrée et sinistre de la pièce. Un autel central, orné de tentacules, semble être le point focal de cette chambre. Un murmure lointain et un fantôme de présence flottent dans l'air, rendant l'atmosphère encore plus étrange. Un secret se cache derrière une porte dissimulée, prête à révéler ses secrets aux courageux explorateurs qui oseront l'ouvrir.",     "tags": [       "salle sacrée",       "anciens",       "ténèbres",       "mystère",       "rituels"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "damp",       "centralFeature": "altar",       "wallDecorations": [         "tentsacles",         "heads of death"       ],       "floorMarkings": [         "spirals",         "crosses"       ],       "architecturalDetails": [         "pillars",         "columns"       ],       "objectsOrFurniture": [         "mysterious objects"       ],       "creaturesOrTraces": [         "ghostly presence"       ],       "exits": [         "hidden door"       ],       "hazards": [         "traps"       ],       "atmosphere": "mysterious and eerie",       "roomPurpose": "sacred chamber",       "csvDescription": "Salle",       "tileNumber": 8     }   } }
