  "10": {   "10": {     "title": "Passage Sacratoire",     "description": "Le passage sacratoire est large et rectangulaire, éclairé par une faible lumière qui se répand dans l'air humide. Des motifs de spirales et de lignes croisées marquent le sol, semblant guider le regard vers le centre. Les murs, couverts d'un tissu de tentacules, semblent vivants et ondulent légèrement. Des colonnes majestueuses soutiennent le plafond, ajoutant à l'atmosphère mystérieuse. Un coffre en bois, fermé et ancien, repose contre un mur, tandis que des ossements dispersés témoignent de sacrifices passés. Un passage secret, dissimulé par un rideau de toile, se trouve à l'extrémité du couloir, menant à une salle plus sombre. Le sol est glissant, rendant chaque pas un défi. Cette chambre sacrée est le cœur d'un rituel ancien, où les morts sont sacrifiés pour l'ascension des vivants.",     "tags": [       "sacrifice",       "rituel",       "couloir",       "mystère",       "tentacules"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "damp",       "centralFeature": "central altar",       "wallDecorations": [         "tented tentacles"       ],       "floorMarkings": [         "spiral patterns",         "crossed lines"       ],       "architecturalDetails": [         "pillars"       ],       "objectsOrFurniture": [         "wooden chest"       ],       "creaturesOrTraces": [         "scattered bones"       ],       "exits": [         "hidden door"       ],       "hazards": [         "slippery floor"       ],       "atmosphere": "mysterious",       "roomPurpose": "sacrificial chamber",       "csvDescription": "Couloir et salle",       "tileNumber": 10     }   } }
