  "11": {   "11": {     "title": "Chambre Sacrée des Anciens",     "description": "La Chambre Sacrée des Anciens est une salle immense, de forme rectangulaire, dont les murs sont recouverts de peintures anciennes et mystérieuses. La lumière y est faible, émanant d'une source inconnue, ce qui ajoute à l'atmosphère étrange et énigmatique de la pièce. Les sols sont marqués de spirales et de croix, symboles de puissance et de protection. Des colonnes et des piliers majestueux soutiennent le plafond, ornés de motifs complexes. Des objets étranges et des symboles mystérieux sont disséminés un peu partout, semblant avoir été laissés là par des cultistes oubliés. À l'extrémité de la pièce, un autel ancien, orné de tentacules et de têtes de mort, semble être le point focal de cette chambre sacrée. Des traces de créatures étranges et des ombres flottantes flottent dans l'air, ajoutant à l'atmosphère sinistre. Un seul passage, dissimulé derrière un rideau de toile, semble mener à une autre partie du donjon.",     "tags": [       "salle",       "ancienne",       "rituel",       "sacrifice",       "mystère"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "ancient",       "centralFeature": "altar",       "wallDecorations": [         "tentsacles",         "heads of death"       ],       "floorMarkings": [         "spirals",         "crosses"       ],       "architecturalDetails": [         "pillars",         "columns"       ],       "objectsOrFurniture": [         "mysterious symbols"       ],       "creaturesOrTraces": [         "ghostly presence"       ],       "exits": [         "hidden door"       ],       "hazards": [         "traps"       ],       "atmosphere": "mysterious and eerie",       "roomPurpose": "sacred chamber",       "csvDescription": "Salle",       "tileNumber": 11     }   } }
