  "12": {   "12": {     "title": "Le Couloir des Sphères",     "description": "Le couloir étendu s'inscrit dans un mur de pierre ancienne, ses murs ornés de tentacules et de têtes de mort qui semblent observer les voyageurs. Le sol, large et rectangulaire, est marqué de spirales et d'un croix au centre, comme si un ancien rituel avait été célébré ici. Des colonnes majestueuses, sculptées de motifs complexes, soutiennent le plafond, ajoutant à l'atmosphère mystérieuse et sacrée du lieu. Un grand table se trouve au fond du couloir, son dessus orné de symboles énigmatiques. Le couloir est éclairé par la lumière naturelle qui pénètre par une ouverture au bout, révélant un espace plus large et éclairé. Les tentacules et têtes de mort sur les murs semblent vivants, leurs regards fixés sur les visiteurs. Le couloir est enchanteur, mais aussi dangereux, car les tentacules peuvent s'agripper aux voyageurs et les entraîner dans un autre monde.",     "tags": [       "couloir",       "rituel",       "sphères",       "tentes",       "mystère"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "natural",       "condition": "ancient",       "centralFeature": "altar",       "wallDecorations": [         "tentsacles",         "heads of death"       ],       "floorMarkings": [         "spirals",         "cross"       ],       "architecturalDetails": [         "pillars",         "columns"       ],       "objectsOrFurniture": [         "table"       ],       "creaturesOrTraces": [         "star"       ],       "exits": [         "none"       ],       "hazards": [         "enchanted"       ],       "atmosphere": "mysterious",       "roomPurpose": "sacred",       "csvDescription": "Couloir avec dessin magique au sol",       "tileNumber": 12     }   } }
