  "14": {   "14": {     "title": "Salle des Échecs Sacrés",     "description": "La salle est petite et rectangulaire, avec un échiquier au centre qui semble avoir été dessiné avec une fine poudre noire. Les murs vieillis sont ornés de reliefs sculptés représentant des figures mystérieuses, et des cercles rituels sont gravés dans le sol. Des piliers robustes soutiennent le plafond, et une fenêtre au fond laisse filtrer une lumière faible, rendant l'atmosphère encore plus mystérieuse. La table au centre de la pièce est recouverte d'un tissu ancien, et une empreinte de pas est visible près de l'échiquier, comme si quelqu'un avait récemment joué. L'eau stagnante au fond de la pièce ajoute une note de danger à cette atmosphère étrange et ancienne.",     "tags": [       "échiquier",       "salle de repos",       "rituels",       "mystère",       "vieillie"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "rectangulaire",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "fenêtre",       "wallDecorations": [         "reliefs sculptés"       ],       "floorMarkings": [         "cercles rituels"       ],       "architecturalDetails": [         "piliers"       ],       "objectsOrFurniture": [         "table"       ],       "creaturesOrTraces": [         "empreinte de pas"       ],       "exits": [],       "hazards": [         "eau stagnante"       ],       "atmosphere": "mystérieuse",       "roomPurpose": "salle de repos",       "csvDescription": "Salle avec échiquier au centre",       "tileNumber": 14     }   } }
