  "162": {   "162": {     "title": "Grotte des Champignons Sacrés",     "description": "La grotte est étroite et basse, avec des parois rugueuses et des formations rocheuses qui semblent avoir vieilli au fil des siècles. La lumière pénètre à peine à travers des fentes minuscules, créant un halo de faible éclat qui éclaire les champignons qui poussent en abondance sur les murs et le sol. Des cercles rituels et des glyphes runiques sont gravés dans le sol, marquant un passage ancien et sacré. Des piliers et des statues de pierre sont disséminés à travers la grotte, ajoutant à son mystère. Le mobilier ancien semble avoir été abandonné depuis longtemps, recouvert de mousse et de champignons. L'atmosphère est pesante et ancienne, comme si la grotte avait gardé des secrets depuis des millénaires. Des eaux stagnantes se trouvent au fond de la grotte, formant un bassin sombre qui reflète la faible lumière qui pénètre à l'intérieur. Les champignons, de toutes les couleurs, semblent vivants et prêts à pousser, ajoutant une touche de vie à ce lieu si ancien et si mystérieux.",     "tags": [       "Grotte",       "Champignons",       "Sacrés",       "Ancien",       "Mystérieux"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "rectangulaire",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels",         "glyphes runiques"       ],       "architecturalDetails": [         "piliers",         "statues"       ],       "objectsOrFurniture": [         "mobilier ancien"       ],       "creaturesOrTraces": [         "pièges"       ],       "exits": [],       "hazards": [         "eau stagnante"       ],       "atmosphere": "mystérieuse et ancienne",       "roomPurpose": "salle de culte ou de rituel",       "csvDescription": "Grotte avec champignons et champignon",       "tileNumber": 162     }   } }
