  "163": {   "163": {     "title": "Grotte des Champignons Sacrés",     "description": "La grotte est étroite et basse, avec des parois rugueuses et des formations rocheuses qui semblent s'écarter pour former un espace carré. La lumière y est faible, filtrant à travers des fentes minuscules dans le plafond, créant un halo de verdure qui éclaire les champignons qui poussent sur les parois. Des cercles rituels sont gravés dans le sol, marquant un espace central qui semble être le point focal de la grotte. Des piliers robustes soutiennent le plafond, ajoutant à l'ambiance sinistre de la pièce. Des traces de vieillissement sont visibles partout, avec des couches de sédiments et des traces de vieilles peintures murales qui se détachent. Le mobilier, si il y en a, est ancien et usé, ajoutant à l'atmosphère de mystère. L'eau stagnante, noire et trouble, remplit une partie de la grotte, créant un danger potentiel. La grotte semble être un lieu de rituel ancien, avec des têtes de mort et des tentacules peints sur les murs, ajoutant une touche d'horreur à l'atmosphère déjà sinistre.",     "tags": [       "Grotte",       "Champignons",       "Rituel Ancien",       "Têtes de Mort",       "Tentacules"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "carrée",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels"       ],       "architecturalDetails": [         "piliers"       ],       "objectsOrFurniture": [         "mobilier"       ],       "creaturesOrTraces": [         "pièges"       ],       "exits": [         "pas de sortie visible"       ],       "hazards": [         "eau stagnante"       ],       "atmosphere": "sinistre",       "roomPurpose": "salle de rituel",       "csvDescription": "Grotte avec champignons",       "tileNumber": 163     }   } }
