  "164": {   "164": {     "title": "Grotte des Anciens",     "description": "La grotte est étroite et sinueuse, ses parois irrégulières sont recouvertes de champignons étranges qui semblent vibrer sous la lumière faible qui filtre à travers les fissures. Les murs vieillis sont marqués de cercles rituels sombres, et des piliers robustes soutiennent le plafond. Des traces de vieilles pierres sculptées sont visibles, et des têtes de mort et des tentacules émergent des ombres. Le mobilier ancien, usé et délabré, semble avoir été abandonné depuis longtemps. L'atmosphère sinistre est accentuée par l'eau stagnante qui s'accumule dans les coins, créant un miroir sombre qui reflète les ombres qui hantent les parois. La grotte est une salle de rituels, et les cercles rituels marquent les emplacements où les anciens pratiquaient leurs cérémonies. Les têtes de mort et les tentacules ajoutent une touche macabre à l'atmosphère, rappelant les sacrifices et les pratiques surnaturelles qui ont eu lieu ici.",     "tags": [       "Grotte",       "Anciens",       "Rituels",       "Champignons",       "Têtes de Mort"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "irrégulière",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels"       ],       "architecturalDetails": [         "piliers"       ],       "objectsOrFurniture": [         "mobilier ancien"       ],       "creaturesOrTraces": [         "squelette"       ],       "exits": [],       "hazards": [         "eau stagnante"       ],       "atmosphere": "sinistre",       "roomPurpose": "salle de rituels",       "csvDescription": "Grotte avec champignons",       "tileNumber": 164     }   } }
