  "165": {   "165": {     "title": "Grotte des Champignons Sacrés",     "description": "La grotte est étroite et basse, avec des parois rugueuses et des formations rocheuses qui semblent avoir vieilli au fil des siècles. La lumière pénètre à peine à travers une ouverture étroite au sommet, créant un halo de faible éclat qui éclaire les champignons qui poussent en abondance sur les murs et le sol. Des cercles rituels et des glyphes runiques sont gravés dans le sol, marquant un passage ancien. Des piliers robustes soutiennent le plafond, tandis que des traces de créatures mystérieuses sillonnent le sol. Le mobilier ancien, usé par le temps, semble avoir été abandonné ici. L'atmosphère sinistre est accentuée par l'eau stagnante qui s'est formée dans un coin, reflétant les ombres des parois. La seule issue semble être un passage étroit qui mène à l'inconnu.",     "tags": [       "Grotte",       "Champignons",       "Rituels",       "Ancien",       "Sacrés"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "carrée",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels",         "glyphes runiques"       ],       "architecturalDetails": [         "piliers"       ],       "objectsOrFurniture": [         "mobilier ancien"       ],       "creaturesOrTraces": [         "traces de créature"       ],       "exits": [         "un seul"       ],       "hazards": [         "eau stagnante"       ],       "atmosphere": "sinistre",       "roomPurpose": "salle de rituel",       "csvDescription": "Grotte avec champignons",       "tileNumber": 165     }   } }
,
  "166": {   "166": {     "title": "Grotte des Champignons Sacrés",     "description": "La grotte est étroite et sinueuse, ses parois irrégulières sont recouvertes de champignons étranges qui semblent vibrer sous la lumière faible qui filtre à travers les fissures. Les murs vieillis sont marqués de cercles rituels et de glyphes runiques, des symboles qui semblent anciens et mystérieux. Des piliers et des colonnes robustes soutiennent le plafond, tandis que des restes de mobilier ancien sont disséminés un peu partout, témoignant d'une présence ancienne. L'atmosphère est pesante, presque oppressante, et les ombres dansent sur les parois, créant des silhouettes étranges. L'eau stagnante au fond de la grotte semble bouillonnante, prête à engloutir tout ce qui s'approche. Les champignons, de couleur verte vif, semblent vivants et pulsent de vie, émettant une odeur étrange qui se mêle à l'air humide de la grotte. Les têtes de mort et les tentacules qui flottent dans l'air ajoutent une touche de menace à l'atmosphère déjà menaçante. Cette grotte est un lieu de culte, un sanctuaire où les anciens pratiquaient des rituels sombres et sacrés.",     "tags": [       "Grotte",       "Champignons Sacrés",       "Rituels Anciens",       "Atmosphère Menacante",       "Salle de Culte"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "irrégulière",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels",         "glyphes runiques"       ],       "architecturalDetails": [         "piliers",         "colonnnes"       ],       "objectsOrFurniture": [         "mobilier ancien"       ],       "creaturesOrTraces": [         "pièges"       ],       "exits": [],       "hazards": [         "eau stagnante"       ],       "atmosphere": "mystérieuse et menaçante",       "roomPurpose": "salle de rituels ou de culte",       "csvDescription": "Grotte avec champignons",       "tileNumber": 166     }   } }
