  "381": {   "381": {     "title": "Salle Sacrée des Anciens",     "description": "La salle est étroite et rectangulaire, avec des murs vieillis et des traces de vieilles peintures. La lumière est faible, filtrant à travers des voiles de poussière qui flottent dans l'air. Des cercles rituels et des glyphes runiques sont gravés dans le sol, marquant un espace sacré. Des piliers massifs soutiennent le plafond, et des statues de pierre sont alignées le long des murs, gardant un air de mystère. Le mobilier ancien est délabré, ajoutant à l'atmosphère ancienne et mystérieuse de la pièce. Une porte murée se trouve à l'extrémité de la salle, et une eau stagnante s'accumule au sol, créant un danger potentiel. La salle semble avoir été utilisée pour des rituels anciens, et les traces de créatures indiquent qu'elle n'est pas abandonnée depuis longtemps.",     "tags": [       "salle sacrée",       "rituels anciens",       "vieillie",       "mystérieuse",       "eau stagnante"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "rectangulaire",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels",         "glyphes runiques"       ],       "architecturalDetails": [         "piliers",         "statues"       ],       "objectsOrFurniture": [         "mobilier ancien"       ],       "creaturesOrTraces": [         "traces de créature"       ],       "exits": [         "porte murée"       ],       "hazards": [         "eau stagnante"       ],       "atmosphere": "mystérieuse et ancienne",       "roomPurpose": "salle de culte",       "csvDescription": "salle ouverte complète",       "tileNumber": 381     }   } }
