  "387": {   "387": {     "title": "Salle des Anciens",     "description": "La salle est étroite et rectangulaire, avec des murs vieillis et des traces de vieilles peintures. La lumière est faible, filtrant à travers des voiles de poussière qui flottent dans l'air. Des cercles rituels et des glyphes runiques sont gravés dans le sol, marquant un espace sacré. Des piliers massifs soutiennent le plafond, et des statues de pierre sont alignées le long des murs, gardant un air de mystère. Le mobilier ancien est délabré, ajoutant à l'atmosphère sombre et menaçante de la pièce. Un seul passage mène à l'extérieur, mais l'eau stagnante au sol rend l'accès difficile. La salle semble être un lieu de culte ou de rituel, avec des têtes de mort et des tentacules peints sur les murs, ajoutant une touche d'horreur à l'ambiance déjà sombre.",     "tags": [       "rituel",       "culte",       "salle sacrée",       "vieillie",       "mystérieuse"     ],     "sourceFeatures": {       "roomSize": "petite",       "roomShape": "rectangulaire",       "lighting": "faible",       "condition": "vieillie",       "centralFeature": "autel",       "wallDecorations": [         "têtes de mort",         "tentacules"       ],       "floorMarkings": [         "cercles rituels",         "glyphes runiques"       ],       "architecturalDetails": [         "piliers",         "statues"       ],       "objectsOrFurniture": [         "mobilier ancien"       ],       "creaturesOrTraces": [         "pièges"       ],       "exits": [         "un seul"       ],       "hazards": [         "eau stagnante"       ],       "atmosphere": "mystérieuse et menaçante",       "roomPurpose": "salle de rituel ou de culte",       "csvDescription": "salle ouverte complète",       "tileNumber": 387     }   } }
,
  "388": {   "388": {     "title": "Chambre Sacrée des Anciens",     "description": "La chambre sacrée des Anciens est une salle ouverte complète, immense et rectangulaire, dont les murs sont couverts de tenticules et de crânes humains. La lumière y est faible, émanant d'une source mystérieuse au centre de la pièce, qui éclaire un grand autel en pierre. Des colonnes et des piliers soutiennent le plafond, ajoutant à l'atmosphère sombre et étrange de la pièce. Des marquages au sol, formant un cercle et un spirale, semblent indiquer un rituel ancien. L'humidité y règne, rendant le sol glissant et humide. À l'ouest, un mur est orné de tentacules et de crânes, tandis qu'un esprit fantomatique plane au-dessus de l'autel, ajoutant une touche de mystère à l'atmosphère déjà sombre. Deux sorties mènent à l'extérieur, l'une au nord et l'autre au sud, mais la présence de l'eau et de mysticisme rend ces sorties potentiellement dangereuses.",     "tags": [       "salle sacrée",       "rituel ancien",       "tenticules",       "crânes",       "autel"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "damp",       "centralFeature": "large stone",       "wallDecorations": [         "tentsacles",         "skulls"       ],       "floorMarkings": [         "spiral",         "circle"       ],       "architecturalDetails": [         "pillars",         "columns"       ],       "objectsOrFurniture": [         "altar"       ],       "creaturesOrTraces": [         "ghostly figure"       ],       "exits": [         "north",         "south"       ],       "hazards": [         "water",         "mystical"       ],       "atmosphere": "mysterious",       "roomPurpose": "sacred chamber",       "csvDescription": "salle ouverte complète",       "tileNumber": 388     }   } }
,
  "389": {   "389": {     "title": "Chambre des Rituels Sacrés",     "description": "La chambre des Rituels Sacrés est une salle ouverte complète, immense et rectangulaire, dont les murs sont recouverts d'un tissu sombre et lisse. La lumière y est faible, filtrant à travers des fenêtres étroites, créant une ambiance mystérieuse et oppressante. La pièce est humide, et des gouttes de condensation perlent sur le sol et les murs. Au centre de la pièce se dresse un autel circulaire, orné de motifs de spirales et de cercles rayonnants, qui semblent être gravés dans le sol. Des piliers robustes et des poutres en bois soutiennent le plafond, ajoutant à l'atmosphère ancienne et sacrée de la pièce. Des tentacules noirs, longs et sinistres, sont suspendus aux murs, ajoutant une touche d'horreur à l'atmosphère. Un tombeau ancien, avec une pierre tombale érodée, se trouve dans un coin de la pièce, évoquant des secrets inexplorés. L'eau stagnante, visible dans un coin de la pièce, est un danger potentiel pour les explorateurs. La chambre des Rituels Sacrés semble être le cœur d'un ancien sanctuaire, où des rituels sombres et sacrés étaient peut-être pratiqués.",     "tags": [       "rituel",       "sacrifice",       "ancien",       "mystère",       "salle des rituels"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "damp",       "centralFeature": "large circular object with stripes",       "wallDecorations": [         "tentacles",         "tombstone"       ],       "floorMarkings": [         "spiral pattern",         "striped circle"       ],       "architecturalDetails": [         "pillars",         "wooden beams"       ],       "objectsOrFurniture": [         "autel"       ],       "creaturesOrTraces": [         "small creature"       ],       "exits": [         "one visible"       ],       "hazards": [         "water"       ],       "atmosphere": "mysterious",       "roomPurpose": "ritual chamber",       "csvDescription": "salle ouverte complète",       "tileNumber": 389     }   } }
