  "390": {   "390": {     "title": "Chambre Sacrée des Anciens",     "description": "La chambre sacrée des Anciens est une salle ouverte complète, immense et rectangulaire, dont les murs sont recouverts de tentacules et de crânes humains. La lumière tamisée émane des fenêtres étroites, révélant une atmosphère mystérieuse et étrange. Les colonnes massives et les piliers sculptés donnent une impression de grandeur et de puissance ancienne. Des cercles rituels et des runes mystiques marquent le sol, tandis qu'un objet mystérieux repose au centre de la pièce. Un murmure subtil et un fantôme hanté flottent dans l'air, ajoutant à l'ambiance sinistre. Un seul passage, dissimulé derrière un rideau de rideau, mène à une autre pièce, mais les pièges et les trappes attendent ceux qui oseront y pénétrer. La chambre sacrée des Anciens est un lieu de culte ancien, où les rituels et les sacrifices étaient pratiqués il y a des siècles.",     "tags": [       "salle sacrée",       "rituels",       "tentesacles",       "crânes",       "sacrifices",       "mystère"     ],     "sourceFeatures": {       "roomSize": "large",       "roomShape": "rectangular",       "lighting": "dim",       "condition": "dilapidated",       "centralFeature": "altar",       "wallDecorations": [         "tentsacles",         "skulls"       ],       "floorMarkings": [         "ritual circles",         "runes"       ],       "architecturalDetails": [         "pillars",         "columns"       ],       "objectsOrFurniture": [         "mysterious object"       ],       "creaturesOrTraces": [         "ghostly presence"       ],       "exits": [         "hidden door"       ],       "hazards": [         "traps"       ],       "atmosphere": "mysterious and eerie",       "roomPurpose": "sacred chamber",       "csvDescription": "salle ouverte complète",       "tileNumber": 390     }   } }
